package compose

import (
	"fmt"
	"regexp"
	"slices"
	"sort"
	"strings"
)

// Groups (ARCHITECTURE 6.1): the chosen services of the apps in a group
// join a network koroku creates, and reach each other as
// <service>.<slug>.koroku.internal.

// GroupNetworkPrefix starts the name of every group network. Slugs cannot
// contain "_", so no app's own network (koroku-<slug>_*) starts with it.
// It must match store.GroupNetworkPrefix.
const GroupNetworkPrefix = "koroku_group_"

// GroupOverrideFileName is the generated file that attaches services to the
// group network. It lives in the app's directory, not in a release, and is
// written again from the database before every `up`.
const GroupOverrideFileName = "group.override.yaml"

// groupNetworkKey is the key the group network has inside the project.
const groupNetworkKey = "koroku_group"

var groupServicePattern = regexp.MustCompile(`^[a-z0-9]([a-z0-9-]*[a-z0-9])?$`)

// ValidGroupService reports whether a service name can join a group: it
// becomes a DNS label in the service's hostname.
func ValidGroupService(name string) bool { return groupServicePattern.MatchString(name) }

// GroupHostname is the name other members use to reach a joined service.
func GroupHostname(service, slug string) string {
	return service + "." + slug + ".koroku.internal"
}

// GroupOverrideParams is the input for GroupOverride.
type GroupOverrideParams struct {
	// Project is the normalized release without the group override.
	Project Project
	Slug    string
	// Network is the group's Docker network (koroku_group_<id>).
	Network  string
	Services []string
}

// GroupOverride renders the group override, or nil when no service joins.
//
// Each joined service lists every network it is already on as well as the
// group network: a service without a networks section is implicitly on
// "default", and naming only the group network would take it off there.
func GroupOverride(p GroupOverrideParams) ([]byte, error) {
	if len(p.Services) == 0 {
		return nil, nil
	}
	if !strings.HasPrefix(p.Network, GroupNetworkPrefix) {
		return nil, fmt.Errorf("group network %q has an unexpected name", p.Network)
	}
	if _, taken := p.Project.Networks[groupNetworkKey]; taken {
		return nil, fmt.Errorf("the Compose file defines a network named %q, which koroku uses for the group", groupNetworkKey)
	}
	services := slices.Clone(p.Services)
	sort.Strings(services)

	var b strings.Builder
	b.WriteString("# Generated by koroku from the app's group. Do not edit: it is rewritten before every start.\n")
	b.WriteString("services:\n")
	for _, name := range services {
		svc, ok := p.Project.Services[name]
		if !ok {
			return nil, fmt.Errorf("service %q joins the group but is not defined in the Compose file", name)
		}
		if !ValidGroupService(name) {
			return nil, fmt.Errorf("service %q cannot join a group: its name is not a valid DNS label", name)
		}
		if svc.NetworkMode != "" {
			return nil, fmt.Errorf("service %q cannot join a group: it uses network_mode %q", name, svc.NetworkMode)
		}
		existing := make([]string, 0, len(svc.Networks))
		for key := range svc.Networks {
			existing = append(existing, key)
		}
		if len(existing) == 0 {
			existing = append(existing, "default")
		}
		sort.Strings(existing)
		fmt.Fprintf(&b, "  %s:\n", quote(name))
		b.WriteString("    networks:\n")
		for _, key := range existing {
			fmt.Fprintf(&b, "      %s: {}\n", quote(key))
		}
		fmt.Fprintf(&b, "      %s:\n", quote(groupNetworkKey))
		b.WriteString("        aliases:\n")
		fmt.Fprintf(&b, "          - %s\n", quote(GroupHostname(name, p.Slug)))
	}
	b.WriteString("networks:\n")
	fmt.Fprintf(&b, "  %s:\n", quote(groupNetworkKey))
	b.WriteString("    external: true\n")
	fmt.Fprintf(&b, "    name: %s\n", quote(p.Network))
	return []byte(b.String()), nil
}

// GroupMember is what the name check needs to know about one app.
type GroupMember struct {
	Slug string
	// Names are the names the app's own services answer to on the app's
	// networks: service names and container names.
	Names []string
	// Joined are the names the app puts on the group network.
	Joined []string
}

// MemberOf derives the names of an app from its normalized project.
func MemberOf(slug string, p Project, joined []string) GroupMember {
	m := GroupMember{Slug: slug}
	for _, name := range p.ServiceNames() {
		svc := p.Services[name]
		m.Names = append(m.Names, name)
		if svc.ContainerName != "" {
			m.Names = append(m.Names, svc.ContainerName)
		}
		if slices.Contains(joined, name) {
			m.Joined = append(m.Joined, name)
			if svc.ContainerName != "" {
				m.Joined = append(m.Joined, svc.ContainerName)
			}
		}
	}
	return m
}

// CheckGroupNames finds names that could resolve to another member. Docker
// answers a name from every network a container is on: while an app's own
// "db" is down, "db" resolves to another member's "db" on the group network
// (ARCHITECTURE 6.1). So no name the app puts on the group network may be a
// name of another member, and the other way around.
func CheckGroupNames(self GroupMember, others []GroupMember) []Violation {
	seen := map[string]bool{}
	var found []Violation
	add := func(name, message string) {
		if seen[name] {
			return
		}
		seen[name] = true
		found = append(found, Violation{Service: name, Rule: RuleGroupNameConflict, Message: message})
	}
	for _, other := range others {
		for _, name := range self.Joined {
			if slices.Contains(other.Names, name) {
				add(name, fmt.Sprintf("%q joins the group network, but app %q in the same group also has a service named %q; rename one of them", name, other.Slug, name))
			}
		}
		for _, name := range other.Joined {
			if slices.Contains(self.Names, name) {
				add(name, fmt.Sprintf("app %q in the same group puts %q on the group network, and this app also has a service named %q; rename one of them", other.Slug, name, name))
			}
		}
	}
	sort.Slice(found, func(i, j int) bool { return found[i].Service < found[j].Service })
	return found
}
